select count(*)
from projects
where leader_account_id = #{leaderAccountId}
  and status = #{status}

select distinct
       p.id, p.route_id, p.region_adcode, p.tag, p.owner_account_id, p.leader_account_id, p.title,
       p.departure_date, p.departure_time, p.start_point_type, p.start_point,
       p.leader_requirements, p.participant_requirements,
       p.max_members, p.current_members, p.status, p.created_at, p.updated_at
from projects p
left join project_members viewer_member
       on viewer_member.project_id = p.id
      and viewer_member.account_id = #{accountId}
      and viewer_member.join_status in ('JOINED', 'COMPLETED')



            p.owner_account_id = #{accountId}


            p.leader_account_id = #{accountId}


            viewer_member.id is not null
            and p.owner_account_id != #{accountId}


            (
                p.owner_account_id = #{accountId}
                or p.leader_account_id = #{accountId}
                or viewer_member.id is not null
            )



        and p.status = #{status}


order by p.departure_date desc, p.departure_time desc, p.created_at desc

select from projects
and ( lower(title) like lower(concat('%', #{keyword}, '%')) or lower(tag) like lower(concat('%', #{keyword}, '%')) or lower(status) like lower(concat('%', #{keyword}, '%')) or lower(start_point) like lower(concat('%', #{keyword}, '%')) or lower(leader_requirements) like lower(concat('%', #{keyword}, '%')) or lower(participant_requirements) like lower(concat('%', #{keyword}, '%')) )
and ( region_adcode = #{filterRegionCode} or left(region_adcode, 4) = left(#{filterRegionCode}, 4) )
and tag = #{filterTag}
and status = #{status}
and departure_date >= #{departureDateFrom}
and departure_date <= #{departureDateTo}
and owner_account_id = #{ownerAccountId}
and leader_account_id = #{leaderAccountId}
and leader_account_id is not null
and leader_account_id is null
and status in ('OPEN', 'MATCHING') and (max_members is null or current_members is null or current_members < max_members)
order by ( case when #{sortRegionCode} is null or #{sortRegionCode} = '' then 0 when region_adcode = #{sortRegionCode} then 100 when left(region_adcode, 4) = left(#{sortRegionCode}, 4) then 50 else 0 end + case when tag is null or tag = '' then 0
when tag in
#{tag}
then 80
else 0 end ) desc, created_at desc

mapper.update:
update projects
set status = #{targetStatus}
where id = #{id}
  and status = #{expectedStatus}

update projects
set current_members = COALESCE(current_members, 0) + #{increment}
where id = #{id}
  and (max_members is null or COALESCE(current_members, 0) + #{increment} <= max_members)
